      'DEFINITIONS' => 
      array (
        'declaringClassName' => 'App\\Support\\Agent\\FeatureFlagManager',
        'implementingClassName' => 'App\\Support\\Agent\\FeatureFlagManager',
        'name' => 'DEFINITIONS',
        'modifiers' => 4,
        'type' => NULL,
        'value' => 
        array (
          'code' => '[
    // Core features
    self::DELEGATION_ENABLED => [\'label\' => \'Delegation API & Engine\', \'description\' => \'Enable delegation API routes, coordinator processing, and scheduled delegation jobs.\'],
    self::DELEGATION_UI_ENABLED => [\'label\' => \'Delegation UI\', \'description\' => \'Enable delegation screens and navigation items in the web interface.\'],
    self::ADVERSARIAL_REVIEW_ENABLED => [\'label\' => \'Adversarial Reviewer\', \'description\' => \'Enable adversarial review passes during summary and plan generation.\'],
    self::MEMORY_ENABLED => [\'label\' => \'Agent Memory\', \'description\' => \'Enable the memory system: Core Memory blocks, Working Memory buffer, and Long-term Memory with BM25 retrieval.\'],
    self::MEMORY_API_ENABLED => [\'label\' => \'Memory API Features\', \'description\' => \'Enable LLM-powered memory features: semantic embeddings (pgvector), entity extraction, and Neo4j knowledge graph. Requires Agent Memory to be enabled and provider keys configured.\'],
    self::REPO_ANALYSIS_ENABLED => [\'label\' => \'Code Analysis\', \'description\' => \'Enable the Code Analysis tool, API lifecycle routes, and Tools navigation entry.\'],
    self::REPO_ANALYSIS_AI_ENABLED => [\'label\' => \'Code Analysis AI Tasks\', \'description\' => \'Enable AI-driven task execution and narrative report synthesis for Code Analysis sessions.\'],
    // Org layer
    self::ORG_ENABLED => [\'label\' => \'Org Layer\', \'description\' => \'Enable organizational AI workforce orchestration layer.\'],
    self::ORG_PROFILES_ENABLED => [\'label\' => \'Org Profiles\', \'description\' => \'Enable agent profile management within the org layer. Requires Org Layer to be enabled.\'],
    self::ORG_RITUALS_ENABLED => [\'label\' => \'Org Rituals\', \'description\' => \'Enable automated ritual scheduling and execution within the org layer. Requires Org Layer to be enabled.\'],
    self::ORG_COUNCILS_ENABLED => [\'label\' => \'Org Councils\', \'description\' => \'Enable council deliberation workflows within the org layer. Requires Org Layer to be enabled.\'],
    self::ORG_COST_ENABLED => [\'label\' => \'Org Cost Governance\', \'description\' => \'Enable cost tracking and budget enforcement for the org layer. Requires Org Layer to be enabled.\'],
    // Compliance
    self::COMPLIANCE_ENABLED => [\'label\' => \'Compliance Engine\', \'description\' => \'Enable the compliance review engine for agent job runs.\'],
    self::COMPLIANCE_PLAN_GATE => [\'label\' => \'Compliance Plan Gate\', \'description\' => \'Require plan compliance checks before job execution. Requires Compliance Engine to be enabled.\'],
    self::COMPLIANCE_VERIFICATION_GATE => [\'label\' => \'Compliance Verification Gate\', \'description\' => \'Require verification compliance checks after job execution. Requires Compliance Engine to be enabled.\'],
    self::COMPLIANCE_ELEGANCE_GATE => [\'label\' => \'Compliance Elegance Gate\', \'description\' => \'Require code elegance checks during compliance review. Requires Compliance Engine to be enabled.\'],
    self::COMPLIANCE_LESSONS => [\'label\' => \'Compliance Lessons\', \'description\' => \'Enable lessons-learned extraction from compliance reviews. Requires Compliance Engine to be enabled.\'],
    // Runtime
    self::STAR_PREAMBLE_ENABLED => [\'label\' => \'STAR Preamble\', \'description\' => \'Inject STAR-format preamble into agent prompts for structured reasoning.\'],
    self::TARGETED_RETRY_ENABLED => [\'label\' => \'Targeted Retry\', \'description\' => \'Enable targeted retry of failed agent runs with adjusted prompts.\'],
    self::WEBHOOKS_ENABLED => [\'label\' => \'Webhooks\', \'description\' => \'Enable outbound webhook notifications for agent events.\'],
    self::MCP_ENABLED => [\'label\' => \'MCP Integration\', \'description\' => \'Enable Model Context Protocol server integration for runtime tool access.\'],
    self::WRAPPER_ENABLED => [\'label\' => \'CLI Wrapper\', \'description\' => \'Enable persistent CLI wrapper process for session reuse and reduced startup overhead.\'],
    self::YIELD_ENABLED => [\'label\' => \'Turn Yielding\', \'description\' => \'Enable automatic turn yielding for long-running agent sessions.\'],
    self::SUBAGENTS_ENABLED => [\'label\' => \'Sub-Agents\', \'description\' => \'Enable spawning of sub-agent processes from messenger runtime sessions.\'],
    self::ENGINEERING_RULES_ENABLED => [\'label\' => \'Engineering Rules Injection\', \'description\' => \'Inject AgentOps engineering rules into agent task context for structured quality enforcement.\'],
    // Messenger
    self::MESSENGER_SYSTEM_NOTIFICATIONS_ENABLED => [\'label\' => \'Messenger System Notifications\', \'description\' => \'Send system event notifications (ritual completions, escalations, job failures) to connected messenger channels.\'],
    // Platform
    self::BILLING_ENABLED => [\'label\' => \'Billing\', \'description\' => \'Enable Stripe-based billing, usage metering, and subscription management.\'],
    self::COMPACTION_ENABLED => [\'label\' => \'Messenger Compaction\', \'description\' => \'Enable automatic compaction of long messenger conversation threads.\'],
    self::TUNNEL_ENABLED => [\'label\' => \'Cloudflare Tunnel\', \'description\' => \'Enable Cloudflare Tunnel integration for secure remote access via a custom hostname.\'],
    // Skills
    self::SKILLS_ENABLED => [\'label\' => \'Agent Skills\', \'description\' => \'Enable the pluggable skill system for extending agent capabilities with domain-specific skill bundles.\'],
    self::SKILLS_UI_ENABLED => [\'label\' => \'Skills UI\', \'description\' => \'Enable skills management pages in the web interface. Requires Agent Skills to be enabled.\'],
    self::SKILLS_LIBRARY_ENABLED => [\'label\' => \'Skills Library\', \'description\' => \'Enable browsing and installing skills from the built-in skill library. Requires Agent Skills to be enabled.\'],
    self::SKILLS_AUTO_RESOLVE => [\'label\' => \'Skills Auto-Resolve\', \'description\' => \'Enable automatic skill matching and LLM ranking during delegation. Requires Agent Skills to be enabled.\'],
    self::SKILLS_VALIDATION_LLM_REVIEW => [\'label\' => \'Skills LLM Review\', \'description\' => \'Enable LLM-assisted content analysis during skill validation via AdversarialReviewerService.\'],
    self::SKILLS_VALIDATION_STRICT_MODE => [\'label\' => \'Skills Strict Validation\', \'description\' => \'Block skill installation on any validation warning, not just errors.\'],
    // Connectors
    self::CONNECTORS_ENABLED => [\'label\' => \'Connectors\', \'description\' => \'Enable the external service connector system for agent integrations with SaaS platforms and APIs.\'],
    self::CONNECTORS_UI_ENABLED => [\'label\' => \'Connectors UI\', \'description\' => \'Enable connector management pages in the web interface. Requires Connectors to be enabled.\'],
    self::CONNECTORS_WEBHOOKS_ENABLED => [\'label\' => \'Connector Webhooks\', \'description\' => \'Enable push-based webhook ingestion from connected external services. Requires Connectors to be enabled.\'],
    self::CONNECTORS_AUTO_RESOLVE => [\'label\' => \'Connector Auto-Resolve\', \'description\' => \'Enable automatic connector discovery and matching during agent delegation. Requires Connectors to be enabled.\'],
    self::CONNECTORS_WRITE_ACTIONS => [\'label\' => \'Connector Write Actions\', \'description\' => \'Enable write/mutate actions on connected services. When disabled, only read-only actions are permitted. Requires Connectors to be enabled.\'],
    self::CONNECTORS_CREDENTIAL_REFRESH => [\'label\' => \'Connector Credential Refresh\', \'description\' => \'Enable automatic background token refresh for OAuth-connected services. Requires Connectors to be enabled.\'],
    // Security (immutable)
    self::SECURITY_CONTENT_TRUST => [\'label\' => \'Content Trust Classification\', \'description\' => \'Enable content trust classification for all tool results. Immutable: cannot be disabled.\'],
    self::SECURITY_INJECTION_DETECTION => [\'label\' => \'Injection Detection\', \'description\' => \'Enable prompt injection detection engine for untrusted content. Immutable: cannot be disabled.\'],
    self::SECURITY_EXFILTRATION_DETECTION => [\'label\' => \'Exfiltration Detection\', \'description\' => \'Enable outbound request monitoring for data exfiltration patterns. Immutable: cannot be disabled.\'],
]',
          'attributes' => 
